import{_ as i,o as l,c as a,ag as o}from"./chunks/framework.BwSLX4ak.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"shitbot/troubleshooting.md","filePath":"shitbot/troubleshooting.md"}'),t={name:"shitbot/troubleshooting.md"};function s(d,e,n,c,r,h){return l(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p>排错时先执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/shitbot status</span></span></code></pre></div><p>记录运行平台、服务端版本、Java 版本，以及出现问题前后的完整控制台日志。</p><h2 id="onebot-一直显示-disconnected" tabindex="-1">OneBot 一直显示 disconnected <a class="header-anchor" href="#onebot-一直显示-disconnected" aria-label="Permalink to &quot;OneBot 一直显示 disconnected&quot;">​</a></h2><p>检查：</p><ol><li>OneBot v11 正向 WebSocket 服务已经开启；</li><li><code>onebot.websocket-url</code> 的协议、地址和端口正确；</li><li><code>access-token</code> 与 OneBot 配置一致；</li><li><code>127.0.0.1</code> 指向的是运行 ShitBot 的机器，不是另一台 OneBot 主机；</li><li>跨主机地址使用 <code>wss://</code>，远程 <code>ws://</code> 默认会被拒绝；</li><li>Java 信任 <code>wss://</code> 证书；</li><li>防火墙允许 Minecraft 实例连接 OneBot；</li><li>OneBot 实现确实兼容 OneBot v11 正向 WebSocket。</li></ol><h2 id="qq-指令没有响应" tabindex="-1">QQ 指令没有响应 <a class="header-anchor" href="#qq-指令没有响应" aria-label="Permalink to &quot;QQ 指令没有响应&quot;">​</a></h2><p>检查：</p><ul><li>群号已加入 <code>onebot.allowed-group-ids</code>，或明确启用了 <code>allow-all-groups</code>；</li><li>OneBot 上报的是群消息；</li><li>对应 <code>onebot.commands.&lt;功能&gt;.enabled</code> 已开启；</li><li>输入文本在 <code>aliases</code> 中；</li><li>指令不处于冷却时间；</li><li>机器人拥有发送群消息和图片的权限；</li><li><code>/shitbot status</code> 显示数据库与 OneBot 正常。</li></ul><h2 id="qq-或-mc-不转发" tabindex="-1"><code>#qq</code> 或 <code>#mc</code> 不转发 <a class="header-anchor" href="#qq-或-mc-不转发" aria-label="Permalink to &quot;`#qq` 或 `#mc` 不转发&quot;">​</a></h2><p>两个方向有独立开关。确认：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">forwarding</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  game-to-group</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  group-to-game</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>如果 <code>require-prefix: true</code>，输入必须包含完整前缀，包括配置中末尾的空格。游戏到 QQ 的目标群来自 <code>allowed-group-ids</code>。</p><h2 id="玩家绑定后仍然被拦截" tabindex="-1">玩家绑定后仍然被拦截 <a class="header-anchor" href="#玩家绑定后仍然被拦截" aria-label="Permalink to &quot;玩家绑定后仍然被拦截&quot;">​</a></h2><p>检查：</p><ul><li>QQ 指令中的游戏 ID 大小写与实际名称完全一致；</li><li>绑定指令使用的是玩家本次登录生成的最新验证码；</li><li>验证码仍在有效期内；</li><li>QQ 未超过 <code>maximum-ids-per-qq</code>；</li><li>群组服的代理和后端连接同一个 MySQL；</li><li>数据库中存在该玩家绑定；</li><li>数据库字符集、排序规则和表结构没有被手动修改。</li></ul><h2 id="数据库连接失败" tabindex="-1">数据库连接失败 <a class="header-anchor" href="#数据库连接失败" aria-label="Permalink to &quot;数据库连接失败&quot;">​</a></h2><p>SQLite：</p><ul><li>插件数据目录可写；</li><li>没有其他进程同时打开共享文件；</li><li>磁盘空间充足。</li></ul><p>MySQL：</p><ul><li>地址、端口、数据库、账号和密码正确；</li><li>MySQL 用户拥有目标数据库权限；</li><li>远程连接使用 <code>sslMode=VERIFY_IDENTITY</code>；</li><li>Java 信任数据库证书；</li><li>服务器能访问 <code>repo.maven.apache.org</code>，或已有兼容 JDBC 驱动；</li><li>防火墙和 MySQL 监听地址允许连接。</li></ul><h2 id="代理提示没有可用子服" tabindex="-1">代理提示没有可用子服 <a class="header-anchor" href="#代理提示没有可用子服" aria-label="Permalink to &quot;代理提示没有可用子服&quot;">​</a></h2><p>检查：</p><ol><li>后端 Spigot 已设为 <code>deployment.role: &quot;backend&quot;</code>；</li><li>后端 listener 已启用；</li><li>endpoint 的名称与后端 <code>server-name</code> 一致；</li><li>地址、端口和 Token 两端一致；</li><li>Token 至少 16 位；</li><li>后端 <code>allowed-proxy-addresses</code> 包含代理实际 IP；</li><li>跨机器连接已启用 TLS，或运行在明确允许的加密隧道；</li><li>防火墙只允许代理访问监听端口；</li><li>代理和后端系统时间正常。</li></ol><p>详细配置见<a href="./proxy-backend.html">代理与后端子服</a>。</p><h2 id="快捷命令提示没有权限" tabindex="-1">快捷命令提示没有权限 <a class="header-anchor" href="#快捷命令提示没有权限" aria-label="Permalink to &quot;快捷命令提示没有权限&quot;">​</a></h2><ul><li>发送者必须已绑定游戏角色，除非明确开启 <code>allow-unbound</code>；</li><li>绑定角色必须拥有快捷命令配置中的 <code>permission</code>；</li><li>离线权限查询需要 LuckPerms、Vault 或可用的离线 OP 信息；</li><li>代理本地命令与后端命令使用不同平台的权限系统；</li><li><code>permission</code> 留空只是不检查游戏权限，并不自动允许未绑定 QQ。</li></ul><h2 id="背包没有快照或材质" tabindex="-1">背包没有快照或材质 <a class="header-anchor" href="#背包没有快照或材质" aria-label="Permalink to &quot;背包没有快照或材质&quot;">​</a></h2><ul><li>玩家至少进入过一次负责保存快照的后端；</li><li><code>inventory.enabled</code> 已开启；</li><li>群组服各端使用同一个 MySQL；</li><li>运行图片渲染的一端可以访问资源包、客户端核心或导出的图标；</li><li>历史快照可能需要玩家重新上线才能取得新版字段和玩家头数据。</li></ul><p>完整说明见<a href="./inventory.html">背包查询与材质配置</a>。</p><h2 id="图片中文显示异常" tabindex="-1">图片中文显示异常 <a class="header-anchor" href="#图片中文显示异常" aria-label="Permalink to &quot;图片中文显示异常&quot;">​</a></h2><p>确认运行环境安装了 <code>image.font-name</code> 和 <code>inventory.font-name</code> 指定的字体。Linux 服务器通常没有 <code>Microsoft YaHei</code>，需要安装字体或改为系统中已有的中文字体。</p><h2 id="高级图片模板启动失败" tabindex="-1">高级图片模板启动失败 <a class="header-anchor" href="#高级图片模板启动失败" aria-label="Permalink to &quot;高级图片模板启动失败&quot;">​</a></h2><p>先确认是否确实需要高级系统；不需要时保持 <code>custom-image-templates.enabled: false</code> 和 <code>image.renderer: &quot;java&quot;</code>。</p><p>需要时检查：</p><ul><li><code>image.renderer: &quot;custom&quot;</code> 必须同时开启高级模板总开关；</li><li>当前 Release 含同版本 <code>ShitBotRenderer-&lt;版本&gt;.jar</code>、<code>.sha256</code> 和 <code>.sig</code>；</li><li>服务器能访问 GitHub Release 下载域名；</li><li><code>components/image-renderer/&lt;版本&gt;/</code> 可写，缓存文件没有被人工替换；</li><li>下载大小、模板资源、画布、像素、图层、循环、渲染时间和队列没有超过配置限制；</li><li>模板已发布，<code>image.custom-template</code> 或群命令中的模板 ID 拼写正确；</li><li>远程图片默认关闭，引用 HTTPS 头像或图片时已明确开启；</li><li>PAPI 模板在 Spigot 后端安装了 PlaceholderAPI，玩家在线，代理 endpoint 与 <code>target-server</code> 正确。</li></ul><p>编辑器打不开时，还要确认 <code>editor.enabled: true</code>，重新执行 <code>/shitbot editor</code> 获取未使用的新链接。反向代理必须使用 HTTPS、保留原始 <code>Host</code>，内部监听仍保持回环地址。</p><h2 id="重载失败" tabindex="-1">重载失败 <a class="header-anchor" href="#重载失败" aria-label="Permalink to &quot;重载失败&quot;">​</a></h2><p><code>/shitbot reload</code> 失败时，旧运行实例会继续保留。查看控制台中最早出现的配置或连接错误，修正后再次重载。</p><p>以下变更建议直接重启：</p><ul><li>替换插件 JAR；</li><li>修改 Java 或服务端核心；</li><li>更换 TLS key store/trust store；</li><li>修改底层网络、防火墙或数据库服务。</li></ul><h2 id="仍然无法解决" tabindex="-1">仍然无法解决 <a class="header-anchor" href="#仍然无法解决" aria-label="Permalink to &quot;仍然无法解决&quot;">​</a></h2><p>在 <a href="https://github.com/hutuyee/ShitBot/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 提交：</p><ul><li>ShitBot 版本；</li><li>平台与服务端版本；</li><li>Java 版本；</li><li>单服、代理或代理—后端部署方式；</li><li>已去除 Token、密码、数据库地址和玩家隐私的日志；</li><li>可以稳定复现问题的步骤。</li></ul><p>不要在 LLBot 群内请求 ShitBot 使用支持。</p>',46)])])}const k=i(t,[["render",s]]);export{u as __pageData,k as default};
